import sys

def is_substring(a, b):
    return a in b

def can_reorder(strings):
    n = len(strings)
    dp = [[False] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if is_substring(strings[i], strings[j]):
                dp[i][j] = True
            else:
                for k in range(i, j):
                    if dp[i][k] and is_substring(strings[k+1], strings[j]):
                        dp[i][j] = True
                        break

    for i in range(n):
        if all(dp[i][j] for j in range(n)):
            result = []
            used = [False] * n
            def dfs(index):
                if used[index]:
                    return
                used[index] = True
                result.append(strings[index])
                for j in range(n):
                    if dp[index][j]:
                        dfs(j)
            dfs(i)
            if len(result) == n:
                return "YES\n" + "\n".join(result)

    return "NO"

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    strings = input[1:]
    print(can_reorder(strings))

